/**
 * Project text data — everything except images.
 * Generated by scripts/import-projects.mjs, then hand-edited.
 *
 * To add a future project:
 *  1. Drop an image folder into src/assets/work/NN_slug/ (main.jpg = cover,
 *     numbered files = gallery order).
 *  2. Append an entry here with the matching assetFolder.
 *  3. Push — the site picks up the images via import.meta.glob automatically.
 */
